//! Slack's sidebar "folders".
//!
//! Slack calls them *channel sections*. The ones the user creates have
//! `type: "standard"`; the others — Direct Messages, Starred, Apps — are
//! generated by the client and contain no channels.
//!
//! The detail you would not guess: the sections are a **linked list** through
//! `next_channel_section_id`, not an ordered array. Using the order the API
//! returns them in gives a sidebar different from the one the user sees.

use crate::api::client::ChannelSection;
use std::collections::{HashMap, HashSet};

/// A folder ready to be drawn.
#[derive(Debug, Clone, PartialEq)]
pub struct Folder {
    pub id: String,
    pub name: String,
    /// The emoji name without the colons, empty if the section has none.
    pub emoji: String,
    /// Indices into the channel list, in the order they should be shown.
    pub channels: Vec<usize>,
}

/// Arranges the channels into folders, in sidebar order.
///
/// `channel_ids` is the channel list as the client knows it; the indices
/// returned point into it. Channels that are in no folder end up in an unnamed
/// section at the bottom: they must not be lost just because the user has not
/// sorted them.
pub fn arrange(
    sections: &[ChannelSection],
    channel_ids: &[String],
    external: &std::collections::HashSet<String>,
) -> Vec<Folder> {
    let index: HashMap<&str, usize> = channel_ids
        .iter()
        .enumerate()
        .map(|(i, id)| (id.as_str(), i))
        .collect();

    let mut folders = Vec::new();
    let mut placed: HashSet<usize> = HashSet::new();

    for s in order(sections) {
        if !s.is_user_section() {
            continue;
        }
        let channels: Vec<usize> = s
            .channel_ids()
            .iter()
            .filter_map(|id| index.get(id.as_str()).copied())
            .inspect(|i| {
                placed.insert(*i);
            })
            .collect();

        // A folder that is empty in our view means its channels are archived
        // or we have not loaded them: showing it would be noise.
        if !channels.is_empty() {
            folders.push(Folder {
                id: s.channel_section_id.clone(),
                name: s.name.clone(),
                emoji: s.emoji.clone(),
                channels,
            });
        }
    }

    let rest: Vec<usize> = (0..channel_ids.len())
        .filter(|i| !placed.contains(i))
        .collect();

    // Spaces shared with other organisations go separately, as Slack does.
    // Its `slack_connect` section exists but is **empty**: the channels are not
    // listed in it, so membership has to be inferred from the channel's own
    // flag.
    let (shared, rest): (Vec<usize>, Vec<usize>) = rest
        .into_iter()
        .partition(|i| external.contains(&channel_ids[*i]));

    if !rest.is_empty() {
        folders.push(Folder {
            id: String::new(),
            name: if folders.is_empty() && shared.is_empty() {
                String::new()
            } else {
                "Altri".to_string()
            },
            emoji: String::new(),
            channels: rest,
        });
    }
    if !shared.is_empty() {
        folders.push(Folder {
            id: "__slack_connect".to_string(),
            name: "Slack Connect".to_string(),
            emoji: "handshake".to_string(),
            channels: shared,
        });
    }
    folders
}

/// Follows `next_channel_section_id` to rebuild the sidebar order.
///
/// If the pointers are inconsistent — a cycle, or an unreachable section — we
/// fall back to the array order for the rest, instead of losing them.
fn order(sections: &[ChannelSection]) -> Vec<&ChannelSection> {
    let by_id: HashMap<&str, &ChannelSection> = sections
        .iter()
        .map(|s| (s.channel_section_id.as_str(), s))
        .collect();

    // The head is the section no other one points to as next.
    let targets: HashSet<&str> = sections
        .iter()
        .filter_map(|s| s.next_channel_section_id.as_deref())
        .collect();
    let head = sections
        .iter()
        .find(|s| !targets.contains(s.channel_section_id.as_str()));

    let mut out = Vec::with_capacity(sections.len());
    let mut seen = HashSet::new();
    let mut cur = head;

    while let Some(s) = cur {
        if !seen.insert(s.channel_section_id.as_str()) {
            break; // a cycle: better to stop than to spin forever
        }
        out.push(s);
        cur = s
            .next_channel_section_id
            .as_deref()
            .and_then(|n| by_id.get(n).copied());
    }

    for s in sections {
        if !seen.contains(s.channel_section_id.as_str()) {
            out.push(s);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn section(id: &str, name: &str, next: Option<&str>, chans: &[&str]) -> ChannelSection {
        ChannelSection {
            channel_section_id: id.into(),
            name: name.into(),
            emoji: String::new(),
            kind: "standard".into(),
            channel_ids_page: crate::api::client::ChannelIdsPage {
                channel_ids: chans.iter().map(|s| s.to_string()).collect(),
            },
            next_channel_section_id: next.map(str::to_string),
        }
    }

    fn ids(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn follows_the_linked_list_not_the_array_order() {
        // In the array: B, C, A. In the list: A -> B -> C.
        let secs = vec![
            section("B", "B", Some("C"), &["c2"]),
            section("C", "C", None, &["c3"]),
            section("A", "A", Some("B"), &["c1"]),
        ];
        let f = arrange(&secs, &ids(&["c1", "c2", "c3"]), &Default::default());
        assert_eq!(
            f.iter().map(|x| x.name.as_str()).collect::<Vec<_>>(),
            ["A", "B", "C"]
        );
    }

    #[test]
    fn channels_outside_any_folder_are_kept() {
        let secs = vec![section("A", "Lavoro", None, &["c1"])];
        let f = arrange(&secs, &ids(&["c1", "orfano"]), &Default::default());
        assert_eq!(f.len(), 2);
        assert_eq!(f[1].name, "Altri");
        assert_eq!(f[1].channels, vec![1]);
    }

    #[test]
    fn without_any_folder_everything_stays_in_one_unnamed_group() {
        let f = arrange(&[], &ids(&["c1", "c2"]), &Default::default());
        assert_eq!(f.len(), 1);
        assert_eq!(f[0].name, "");
        assert_eq!(f[0].channels, vec![0, 1]);
    }

    #[test]
    fn system_sections_are_skipped() {
        let mut dms = section("D", "Direct Messages", None, &[]);
        dms.kind = "direct_messages".into();
        let f = arrange(
            &[dms, section("A", "Lavoro", None, &["c1"])],
            &ids(&["c1"]),
            &Default::default(),
        );
        assert_eq!(
            f.iter().map(|x| x.name.as_str()).collect::<Vec<_>>(),
            ["Lavoro"]
        );
    }

    #[test]
    fn empty_folders_are_not_shown() {
        // The folder points at an archived channel we have not loaded.
        let f = arrange(
            &[section("A", "Vuota", None, &["sparito"])],
            &ids(&["c1"]),
            &Default::default(),
        );
        assert_eq!(f.len(), 1);
        assert_eq!(f[0].name, "");
    }

    #[test]
    fn a_cycle_does_not_hang_and_loses_nothing() {
        let secs = vec![
            section("A", "A", Some("B"), &["c1"]),
            section("B", "B", Some("A"), &["c2"]),
        ];
        let f = arrange(&secs, &ids(&["c1", "c2"]), &Default::default());
        assert_eq!(f.len(), 2, "both folders must appear");
    }

    #[test]
    fn a_channel_listed_in_two_folders_is_not_duplicated_into_others() {
        let secs = vec![
            section("A", "A", Some("B"), &["c1"]),
            section("B", "B", None, &["c1"]),
        ];
        let f = arrange(&secs, &ids(&["c1"]), &Default::default());
        assert_eq!(f.len(), 2);
        assert!(
            f.iter().all(|x| x.name != "Altri"),
            "c1 is already placed, it must not end up in the orphans"
        );
    }
}
